<script setup>
import{onMounted,ref}from'vue';import AdminLayout from'../../components/admin/AdminLayout.vue';import{adminJson}from'../../services/adminAuth';const rows=ref([]),search=ref(''),loading=ref(false),error=ref('');async function load(){loading.value=true;error.value='';try{rows.value=(await adminJson(`/api/admin/donors?search=${encodeURIComponent(search.value)}`)).data}catch(e){error.value=e.message}finally{loading.value=false}}onMounted(load)
</script>
<template><AdminLayout><div class="admin-title"><div><p>দান ব্যবস্থাপনা</p><h1>দাতাগণ</h1></div></div><section class="panel"><form class="management-toolbar" @submit.prevent="load"><input v-model="search" placeholder="নাম অথবা মোবাইল দিয়ে খুঁজুন"><button class="admin-button">খুঁজুন</button></form><p v-if="error" class="login-error">{{error}}</p><div class="table-wrap"><table><thead><tr><th>দাতার নাম</th><th>মোবাইল</th><th>নিশ্চিত দান</th><th>মোট পরিমাণ</th><th>সর্বশেষ দান</th></tr></thead><tbody><tr v-if="loading"><td colspan="5">লোড হচ্ছে…</td></tr><tr v-else-if="!rows.length"><td colspan="5"><div class="empty compact">কোনো দাতা পাওয়া যায়নি।</div></td></tr><tr v-for="item in rows" :key="item.id"><td><b>{{item.name}}</b></td><td>{{item.mobile}}</td><td>{{item.confirmed_donations_count}}</td><td>৳ {{Number(item.confirmed_amount||0).toLocaleString('bn-BD')}}</td><td>{{item.last_donation_at?new Date(item.last_donation_at).toLocaleDateString('bn-BD'):'—'}}</td></tr></tbody></table></div></section></AdminLayout></template>
